"""AZ-305 domain 3: Design business continuity solutions (15–20%)."""
from _az305 import ML, S, L, anim, cfg, lab, qa, row

anim("az305-bcdr-sim", "Backup and disaster recovery design", ["AZ305-3.1.1", "AZ305-3.1.2", "AZ305-3.1.3", "AZ305-3.1.4"], "Pick Azure Backup, Site Recovery, failover groups, point-in-time restore or long-term retention for each recovery requirement.")
anim("az305-ha-sim", "High availability design and composite SLA", ["AZ305-3.2.1", "AZ305-3.2.2", "AZ305-3.2.3"], "Choose zones, availability sets or multi-region designs, data replication options, and calculate a composite SLA.")

REL = ML + "azure/reliability/"
SQL = ML + "azure/azure-sql/"
WAF = ML + "azure/well-architected/"

# ================================================================ 3.1 backup and disaster recovery
L(
    id="az305-bcdr", title="Design backup and disaster recovery", objectives=["AZ305-3.1.1", "AZ305-3.1.2", "AZ305-3.1.3", "AZ305-3.1.4"], minutes=50,
    objective="Recommend recovery solutions for Azure and hybrid workloads that meet RPO and RTO, and backup and recovery for compute, databases and unstructured data.",
    prereqs=[("Backup vaults and policies (AZ-104)", "AZ104-5.2.1", "az104-backup-vaults"), ("Site Recovery (AZ-104)", "AZ104-5.2.5", "az104-site-recovery")],
    foundation=[
        "Two numbers drive every recovery design. RPO (recovery point objective): how much data you can afford to lose, measured in time. RTO (recovery time objective): how long you can be down.",
        "Backup lets you go back in time (after a mistake or ransomware). Disaster recovery keeps the service running somewhere else (after a regional outage). Most systems need both.",
        "Smaller RPO and RTO cost more, so set them per workload with the business.",
    ],
    engineer=[
        "Recovery design: classify workloads (mission-critical, business-critical, other) with RPO/RTO targets; choose backup, replication or active-active accordingly; document runbooks and test failovers regularly (Site Recovery test failover doesn't affect production). Use paired or chosen secondary regions; consider data residency.",
        "Compute: Azure Backup for VMs (Standard policy: daily; Enhanced: every 4–24 hours, longer instant-restore snapshots, required for Trusted Launch in the portal), restore as new VM, replace disks or file-level recovery. Azure Site Recovery replicates Azure VMs to another region (and VMware, Hyper-V or physical servers to Azure) with crash-consistent recovery points every few minutes, app-consistent points on a schedule, recovery plans for multi-tier ordering, and test failovers. Hybrid: MARS agent for files and folders, Azure Backup Server or DPM for on-premises workloads.",
        "Databases: Azure SQL automated backups with point-in-time restore (1–35 days), long-term retention (weekly, monthly, yearly up to 10 years), geo-restore from geo-redundant backups (RPO about 1 hour, RTO up to about 12 hours), active geo-replication (readable secondaries, RPO about 5 seconds) and auto-failover groups (listener endpoints, SQL Database and Managed Instance). SQL Server in VMs: Azure Backup with 15-minute log backups. Cosmos DB: continuous backup with point-in-time restore (7 or 30 days) or periodic backup.",
        "Unstructured data: blob soft delete, versioning, point-in-time restore, operational and vaulted backup for blobs, object replication; Azure Files share snapshots and Azure Backup for Files (snapshot and vaulted tiers); geo-redundant storage with customer-managed failover. Protect backups: vault soft delete, immutable vaults, multi-user authorization with Resource Guard, and cross-region restore on GRS vaults.",
    ],
    anim=("az305-bcdr-sim", "Choose the backup or disaster recovery solution for each recovery requirement."),
    example=("RPO/RTO tiers for an insurer", [
        "Mission-critical claims system (RPO 5 minutes, RTO 1 hour): VMs replicated with Site Recovery to a second region, database in an auto-failover group, quarterly test failovers. Daily Enhanced-policy backups protect against corruption and ransomware.",
        "Internal tools (RPO 24 hours, RTO 24 hours): daily Azure Backup only, with cross-region restore. Documents: versioning, soft delete and vaulted blob backup; yearly SQL long-term retention for 7 years.",
    ]),
    config=cfg(["Recovery Services vault > Backup / Site Recovery: enable replication, recovery plans, test failover.", "Backup vault > Backup policies (blobs, disks, PostgreSQL).", "SQL server > Backups: retention policies, long-term retention; Failover groups."],
               cli="az backup protection enable-for-vm -g rg-bcdr --vault-name rsv-weu --vm vm-app01 --policy-name EnhancedPolicy\naz sql failover-group create -g rg-data -s sql-weu --partner-server sql-neu -n fog-claims --add-db db-claims --failover-policy Automatic",
               ps="New-AzSqlDatabaseFailoverGroup -ResourceGroupName rg-data -ServerName sql-weu -PartnerServerName sql-neu -FailoverGroupName fog-claims -FailoverPolicy Automatic"),
    lab=lab("Pick the recovery solution for each requirement.", [("recovery", "recovery solution")], ["Answer every case.", "For each answer, say which of RPO or RTO it mainly improves."],
            ["Site Recovery for regional DR of VMs", "Backup for point-in-time recovery"], ["Using replication alone against ransomware", "Never testing failover"]),
    troubleshooting=[("After ransomware, the DR copy is encrypted too.", "Replication copies every change.", "Restore from point-in-time backups (protected with immutable vault and soft delete)."),
                     ("The app can't connect after a SQL geo-failover.", "Connection string points to the old primary server.", "Use the failover group's listener endpoint.")],
    comparisons=[("Azure Backup vs Site Recovery", "Backup restores data to a point in time; Site Recovery fails whole workloads over to another region."), ("Geo-restore vs geo-replication", "Geo-restore: cheap, hours of RTO and ~1 h RPO. Geo-replication: running secondary, seconds of RPO.")],
    misconceptions=[("Replication is a backup.", "It replicates corruption and deletions too."), ("RTO is how much data you lose.", "That is RPO; RTO is downtime.")],
    decisions=["Set RPO/RTO per workload tier.", "Backup for every workload; DR (Site Recovery, failover groups) for those that need it.", "Protect backups: soft delete, immutability, Resource Guard; test restores and failovers."],
    docs=[("Business continuity, HA and DR", REL + "concept-business-continuity-high-availability-disaster-recovery"), ("About Site Recovery", ML + "azure/site-recovery/site-recovery-overview"), ("What is Azure Backup?", ML + "azure/backup/backup-overview"), ("Azure SQL business continuity", SQL + "database/business-continuity-high-availability-disaster-recover-hadr-overview"), ("Auto-failover groups", SQL + "database/failover-group-sql-db")],
    walk_=("Lose as little data and as little time as the business can accept, and no more than it pays for.",
           ["RPO and RTO", "Backup vs disaster recovery", "Recovery for VMs and databases", "Recovery for files and blobs, and protecting backups"],
           row(0, ("prim", "Primary region", "globe"), ("vm", "VMs", "compute"), ("db", "SQL database", "database"), ("blob", "Blobs + files", "storage"))
           + row(1, ("bk", "Azure Backup", "security", "back in time"), ("asr", "Site Recovery", "service", "fail over"), ("fog", "Failover group", "database", "geo-replica"))
           + row(2, ("sec", "Secondary region", "globe"), ("imm", "Immutable vault", "security", "protect backups")),
           [S("problem", "Problem", "A region fails — or ransomware strikes", "Different disasters need different answers. First agree two numbers with the business.", add=["prim"]),
            S("concept", "Targets", "RPO and RTO", "RPO: how much data you can lose (minutes? a day?). RTO: how long you can be down. Smaller numbers mean more cost, so set them per workload.", learn=[0], stats=[("RPO", "data loss"), ("RTO", "downtime")]),
            S("concept", "Two tools", "Backup goes back in time; DR goes somewhere else", "Backups recover from mistakes, corruption and ransomware. Disaster recovery replicates to another region so the service keeps running when a region fails.", add=["vm", "bk", "asr"], edges=[("vm", "bk", "daily / hourly"), ("vm", "asr", "replicate")], learn=[1], warn="Replication copies ransomware damage too — you still need backups."),
            S("technique", "Compute + data", "VMs and databases", "VMs: Azure Backup plus Site Recovery for regional failover with test failovers. SQL: point-in-time restore (up to 35 days), long-term retention (up to 10 years), and failover groups for a geo-replica with seconds of RPO.", add=["db", "fog", "sec"], edges=[("db", "fog"), ("asr", "sec"), ("fog", "sec")], learn=[2]),
            S("technique", "Files + protection", "Blobs, files and safe backups", "Blobs: soft delete, versioning, vaulted backup. Files: share snapshots and Azure Backup. Protect the backups themselves with soft delete, immutable vaults and Resource Guard.", add=["blob", "imm"], edges=[("blob", "bk"), ("bk", "imm")], learn=[3]),
            S("recap", "Recap", "Recovery design", "Targets first, then tools.", recap=["RPO = data loss; RTO = downtime", "Backup (time) vs DR (place)", "VMs: Backup + Site Recovery; SQL: PITR, LTR, failover groups", "Blobs/files: versioning, snapshots, vaulted backup; protect backups"])]),
)
qa("AZ305-3.1.1", 2, "scenario", "An app's VMs must run in another region within a few hours of a regional outage, losing at most a few minutes of data. What do you recommend?", [("Azure Site Recovery replication to a secondary region", "Correct."), ("Daily Azure Backup with cross-region restore", "RPO up to a day and slower recovery."), ("Availability zones", "Don't protect against a regional outage."), ("Snapshots in the same region", "Lost with the region.")], "a", "Site Recovery provides minute-level RPO and orchestrated regional failover.", ML + "azure/site-recovery/site-recovery-overview")
qa("AZ305-3.1.1", 2, "single", "A workload has an RPO of 24 hours and an RTO of 48 hours. What is the most cost-effective recovery design?", [("Daily backups with Azure Backup", "Correct."), ("Active-active in two regions", "Far more than needed."), ("Site Recovery with recovery plans", "More cost than these targets need."), ("No protection", "Doesn't meet the targets.")], "a", "Relaxed targets are met by backup alone.", ML + "azure/backup/backup-overview")
qa("AZ305-3.1.1", 3, "scenario", "Disaster recovery must be proven every quarter without affecting production. What do you recommend?", [("Site Recovery test failover into an isolated network", "Correct."), ("Planned failover of production every quarter", "Disrupts production."), ("Restore a backup to the same VNet", "Risk of conflicts."), ("Review the runbook only", "Not a test.")], "a", "Test failover creates VMs in an isolated network while replication continues.", ML + "azure/site-recovery/azure-to-azure-tutorial-dr-drill")
qa("AZ305-3.1.2", 2, "scenario", "Ransomware encrypted a VM's disks this morning. You need it back as it was two days ago. What do you use?", [("Azure Backup restore from a recovery point", "Correct."), ("Site Recovery failover", "Replicas may contain the encrypted data."), ("Availability set", "HA, not recovery."), ("Redeploy the VM", "Same disks.")], "a", "Point-in-time backups recover from corruption and ransomware.", ML + "azure/backup/backup-azure-arm-restore-vms")
qa("AZ305-3.1.2", 2, "scenario", "Backups must survive even if an attacker with admin rights tries to delete them or shorten retention. What do you recommend?", [("Immutable vault plus soft delete and multi-user authorization (Resource Guard)", "Correct."), ("A resource lock only", "Admins can remove locks."), ("Daily backups to a second subscription without protection", "Still deletable."), ("Site Recovery", "Not backup protection.")], "a", "Immutability, soft delete and MUA protect backups against malicious admins.", ML + "azure/backup/backup-azure-immutable-vault-concept")
qa("AZ305-3.1.2", 2, "scenario", "File servers on-premises must back up selected folders to Azure without extra servers. What do you recommend?", [("The MARS agent with a Recovery Services vault", "Correct."), ("Site Recovery", "Replicates whole machines."), ("Azure Backup Server", "Needs a dedicated server."), ("AzCopy", "Copy, not backup.")], "a", "The MARS agent backs up files, folders and system state directly to Azure.", ML + "azure/backup/backup-azure-about-mars")
qa("AZ305-3.1.3", 2, "scenario", "A SQL database must fail over to another region with an RPO of seconds, and apps must not change connection strings. What do you recommend?", [("An auto-failover group with its listener endpoint", "Correct."), ("Geo-restore", "RPO about an hour and long RTO."), ("Long-term retention", "For compliance, not DR."), ("Zone redundancy", "Single region.")], "a", "Failover groups replicate asynchronously and provide stable listener endpoints.", SQL + "database/failover-group-sql-db")
qa("AZ305-3.1.3", 2, "scenario", "Auditors require yearly backups of a SQL database kept for 7 years. What do you configure?", [("Long-term retention (LTR) with yearly backups for 7 years", "Correct."), ("Point-in-time restore retention of 7 years", "PITR is limited to 35 days."), ("Geo-replication", "Not retention."), ("Export a BACPAC manually each year", "Manual and error-prone.")], "a", "LTR keeps full backups up to 10 years.", SQL + "database/long-term-retention-overview")
qa("AZ305-3.1.3", 3, "scenario", "A developer deleted rows in a production Azure SQL database 30 minutes ago. What is the fastest supported recovery?", [("Point-in-time restore to a new database just before the deletion, then copy the rows back", "Correct."), ("Fail over the failover group", "The geo-secondary has the deletion too."), ("Restore the latest LTR backup", "Could be a week old."), ("Geo-restore", "Older data and slower.")], "a", "PITR restores to any point in the retention window as a new database.", SQL + "database/recovery-using-backups")
qa("AZ305-3.1.4", 2, "scenario", "Users overwrite blobs by mistake and occasionally delete them. You need recovery for 30 days at low effort. What do you recommend?", [("Blob versioning plus soft delete (30 days)", "Correct."), ("GRS", "Replicates the mistakes."), ("Archive tier", "Cost tier, not protection."), ("Daily AzCopy to another account", "Manual and costly.")], "a", "Versioning recovers overwrites; soft delete recovers deletions.", ML + "azure/storage/blobs/data-protection-overview")
qa("AZ305-3.1.4", 2, "scenario", "An Azure file share must be backed up daily with 30-day retention, and single files must be restorable by admins. What do you recommend?", [("Azure Backup for Azure Files", "Correct: snapshot-based policy with item-level restore."), ("Blob soft delete", "Not for file shares."), ("Site Recovery", "VM replication."), ("Object replication", "Blob only.")], "a", "Azure Backup manages share snapshots (and vaulted copies) with retention and item-level restore.", ML + "azure/backup/azure-file-share-backup-overview")
qa("AZ305-3.1.4", 3, "scenario", "Blob data must be recoverable even if the storage account is deleted, with copies in another region. What do you recommend?", [("Vaulted backup for blobs in a geo-redundant Backup vault", "Correct."), ("Operational backup only", "Lives in the source account."), ("Soft delete", "Lost with the account."), ("RA-GZRS", "Account deletion removes all copies.")], "a", "Vaulted backup copies data to a Backup vault, which can be geo-redundant.", ML + "azure/backup/blob-backup-overview")

# ================================================================ 3.2 high availability
L(
    id="az305-high-availability", title="Design for high availability", objectives=["AZ305-3.2.1", "AZ305-3.2.2", "AZ305-3.2.3"], minutes=45,
    objective="Recommend high availability for compute, relational data and semi-structured and unstructured data, and calculate composite SLAs.",
    prereqs=[("Availability sets and zones (AZ-104)", "AZ104-3.2.6", "az104-vm-availability")],
    foundation=[
        "High availability means the app keeps running when a part fails. Availability zones protect against a datacenter failure; a second region protects against a regional one.",
        "Every service has an SLA. When an app needs several services at once, their SLAs multiply, so the whole is less available than each part. Redundant copies raise availability again.",
    ],
    engineer=[
        "Compute: spread VMs or VM Scale Sets (Flexible orchestration) across availability zones behind a zone-redundant Standard Load Balancer or Application Gateway v2; use zone-redundant App Service plans, Container Apps environments, AKS node pools across zones and Functions on zone-redundant plans. Availability sets only for regions without zones. Multi-region: active-passive (warm or cold standby) or active-active behind Front Door or Traffic Manager, with health probes and automated failover.",
        "Relational data: Azure SQL Database and Managed Instance include built-in HA; enable zone redundancy for zone failures; use active geo-replication or failover groups for regional resilience and readable secondaries. SQL Server on VMs: Always On availability groups across zones or regions. PostgreSQL and MySQL flexible server: zone-redundant HA with a standby replica.",
        "Semi-structured and unstructured data: Cosmos DB with availability zones and multiple regions (service-managed failover; multi-region writes for the highest availability, with conflict resolution); storage redundancy ZRS, GZRS or RA-GZRS; RA- endpoints let apps read during a regional outage.",
        "Composite SLA: services needed in series multiply (99.95% × 99.99% ≈ 99.94%). N independent copies in parallel: 1 − (1 − SLA)^N. Add the global router's SLA in series. Use the Well-Architected Framework reliability pillar to set targets, find single points of failure and design health modelling.",
    ],
    anim=("az305-ha-sim", "Pick zone, set or multi-region designs, data HA options, and calculate composite SLAs."),
    example=("99.99% for an online shop", [
        "Single region: App Service (zone-redundant), SQL Database (zone-redundant) and a cache give about 99.84% composite — below target. The architect deploys the stack in two regions, active-active behind Front Door.",
        "Two regions raise the stack to about 99.9997% before the router; multiplied by Front Door's SLA the design clears 99.99%. Product data uses Cosmos DB with multi-region writes; images use RA-GZRS storage.",
    ]),
    config=cfg(["App Service plan > Zone redundancy; VM Scale Set > Availability zones.", "SQL database > Compute + storage > Zone redundancy; Failover groups.", "Cosmos DB > Replicate data globally; Multi-region writes."],
               cli="az appservice plan create -g rg-web -n asp-shop --sku P1v3 --zone-redundant --number-of-workers 2\naz sql db update -g rg-data -s sql-weu -n db-shop --zone-redundant true\naz cosmosdb update -g rg-data -n cosmos-shop --enable-multiple-write-locations true",
               ps="Update-AzCosmosDBAccount -ResourceGroupName rg-data -Name cosmos-shop -EnableMultipleWriteLocations:$true"),
    lab=lab("Design HA for compute and data, then check the composite SLA.", [("high-availability", "availability design"), ("data-ha", "data availability option")],
            ["Answer every case in both trainers.", "Open the composite SLA calculator: read the starting single-region result, try 'One region without the cache', then 'Same stack in two regions', and compare each with the 99.95% target."],
            ["Zones for datacenter failure; regions for regional failure", "SLAs multiply in series; redundancy raises them"], ["Assuming a chain of services is as available as its best part", "Using availability sets where zones exist"],
            extra=[("sla-multi-region", "Calculated a two-region composite SLA"), ("sla-meets", "Reached the business target")]),
    troubleshooting=[("Downtime during a zone outage even though VMs were in a scale set.", "Scale set not spread across zones.", "Deploy the scale set across zones 1, 2 and 3 with a zone-redundant load balancer."),
                     ("Composite availability is lower than every single service's SLA.", "Dependencies multiply.", "Remove dependencies, add redundancy or a second region.")],
    comparisons=[("Active-active vs active-passive", "Active-active serves from both regions (higher cost, near-zero failover); active-passive keeps a standby (lower cost, longer RTO)."), ("Zone-redundant vs geo-redundant", "Zones: one region, survives a datacenter outage; geo: another region, survives a regional outage.")],
    misconceptions=[("A 99.99% database makes the app 99.99%.", "The app's availability is the product of everything it depends on."), ("Availability sets protect against datacenter failure.", "They protect against rack failures inside one datacenter.")],
    decisions=["Zone-redundant by default where available.", "Second region only when RTO/SLA needs it.", "Calculate composite SLA and remove single points of failure."],
    docs=[("What are availability zones?", REL + "availability-zones-overview"), ("Reliability: target metrics (composite SLA)", WAF + "reliability/metrics"), ("Azure SQL high availability", SQL + "database/high-availability-sla-local-zone-redundancy"), ("High availability in Cosmos DB", ML + "azure/reliability/reliability-cosmos-db-nosql"), ("Multi-region web app", ML + "azure/architecture/web-apps/app-service/architectures/multi-region")],
    walk_=("Keep the app up when a rack, a datacenter or a whole region fails — and prove it with numbers.",
           ["Zones vs sets vs regions for compute", "HA for relational data", "HA for Cosmos DB and storage", "Composite SLA maths"],
           row(0, ("fd", "Front Door", "globe", "global router"), ("r1", "Region 1", "globe"), ("r2", "Region 2", "globe"))
           + row(1, ("z1", "Zone 1", "compute"), ("z2", "Zone 2", "compute"), ("z3", "Zone 3", "compute"))
           + row(2, ("sql", "SQL zone-redundant + geo", "database"), ("cos", "Cosmos multi-region", "database"), ("st", "RA-GZRS storage", "storage")),
           [S("problem", "Problem", "The target is 99.99%", "The business wants less than 5 minutes of downtime a month. Where can things fail, and what does each part promise?", add=["r1"]),
            S("concept", "Compute", "Zones, sets and regions", "Spread instances across availability zones (separate datacenters) behind a zone-redundant load balancer. Availability sets only protect against rack failures, for regions without zones. A second region protects against regional failure.", add=["z1", "z2", "z3"], edges=[("r1", "z1"), ("r1", "z2"), ("r1", "z3")], learn=[0]),
            S("technique", "Relational", "SQL stays up", "Turn on zone redundancy for zone failures. Add geo-replication or a failover group for regional failures and readable secondaries.", add=["sql"], edges=[("z2", "sql")], learn=[1]),
            S("technique", "Other data", "Cosmos DB and storage", "Cosmos DB with zones and multiple regions; multi-region writes for the highest availability. Storage with ZRS, GZRS or RA-GZRS for reads during a regional outage.", add=["cos", "st"], learn=[2]),
            S("technique", "The maths", "Composite SLA", "Things you need together multiply: 99.95% × 99.99% × 99.9% ≈ 99.84%. Two independent copies: 1 − (1 − 0.9984)² ≈ 99.9997%. Then multiply by the router's SLA.", add=["fd", "r2"], edges=[("fd", "r1"), ("fd", "r2")], learn=[3], stats=[("1 region", "≈ 99.84%"), ("2 regions + router", "≈ 99.99%")], tip="Try it in the composite SLA calculator below."),
            S("recap", "Recap", "HA design", "Remove single points of failure.", recap=["Zones by default; sets only without zones; regions for regional failure", "SQL: zone-redundant + failover group", "Cosmos multi-region; ZRS/GZRS/RA-GZRS", "Series multiply; parallel = 1 − (1 − SLA)^N"])]),
)
qa("AZ305-3.2.1", 2, "scenario", "A VM-based web tier must keep running if a datacenter in the region fails. The region has availability zones. What do you recommend?", [("A VM Scale Set across zones 1, 2 and 3 behind a zone-redundant Standard Load Balancer", "Correct."), ("An availability set", "One datacenter."), ("A single larger VM", "Single point of failure."), ("Two VMs in the same zone", "Same datacenter.")], "a", "Zones are separate datacenters; spread instances across them.", REL + "availability-zones-overview")
qa("AZ305-3.2.1", 3, "architecture", "An app must survive a full regional outage with near-zero downtime and serve users from the nearest region. What do you recommend?", [("Active-active deployments in two regions behind Azure Front Door", "Correct."), ("Active-passive with manual DNS change", "Slow failover."), ("Zone-redundant deployment in one region", "Doesn't survive a regional outage."), ("Daily backups to another region", "Hours of downtime.")], "a", "Active-active behind a global router serves from healthy regions and fails over automatically.", ML + "azure/architecture/web-apps/app-service/architectures/multi-region")
qa("AZ305-3.2.1", 3, "scenario", "An app needs a web tier (99.95%) and a database (99.99%) at the same time. What is its composite SLA?", [("About 99.94%", "Correct: 0.9995 × 0.9999."), ("99.99%", "Takes only the best part."), ("99.95%", "Ignores the database."), ("99.999%", "Composite availability is lower, not higher.")], "a", "Services needed together multiply their SLAs.", WAF + "reliability/metrics")
qa("AZ305-3.2.2", 2, "scenario", "An Azure SQL database must survive a zone outage with no data loss and without changing regions. What do you recommend?", [("Enable zone redundancy on the database", "Correct."), ("Active geo-replication", "Targets regional failures; asynchronous."), ("Long-term retention", "Backups, not HA."), ("Elastic pool", "Resource sharing.")], "a", "Zone-redundant configuration places synchronous replicas in different zones.", SQL + "database/high-availability-sla-local-zone-redundancy")
qa("AZ305-3.2.2", 2, "scenario", "SQL Server on Azure VMs must stay available during a zone failure with automatic failover. What do you recommend?", [("An Always On availability group with replicas in different zones", "Correct."), ("One VM with Premium SSD", "Single point of failure."), ("Azure Backup", "Recovery, not HA."), ("SQL Database failover group", "For PaaS, not SQL on VMs.")], "a", "Availability groups replicate databases across VMs placed in different zones.", SQL + "virtual-machines/windows/availability-group-overview")
qa("AZ305-3.2.2", 3, "scenario", "A SQL Managed Instance must continue in another region after a regional outage, and reports should read from the secondary. What do you recommend?", [("A failover group for the managed instance", "Correct: readable secondary and listener endpoints."), ("Active geo-replication", "Not available for Managed Instance."), ("Zone redundancy", "Single region."), ("Geo-restore only", "Long RTO.")], "a", "Managed Instance uses failover groups for geo-replication.", SQL + "managed-instance/failover-group-sql-mi")
qa("AZ305-3.2.3", 2, "scenario", "A global app must accept writes in every region and stay writable during a regional outage. What do you recommend?", [("Cosmos DB with multi-region writes", "Correct."), ("Cosmos DB with a single write region", "Writes pause until failover."), ("Table Storage with GRS", "Single write region."), ("SQL Database geo-replication", "Single writable primary.")], "a", "Multi-region writes let every region accept writes.", ML + "azure/cosmos-db/high-availability")
qa("AZ305-3.2.3", 2, "scenario", "Images must remain readable during a regional outage without waiting for failover, and survive a zone failure. Which redundancy?", [("RA-GZRS", "Correct."), ("GZRS", "Secondary not readable until failover."), ("ZRS", "No secondary region."), ("LRS", "Single datacenter.")], "a", "RA-GZRS combines zones with a readable secondary region.", ML + "azure/storage/common/storage-redundancy")
qa("AZ305-3.2.3", 2, "single", "Which Cosmos DB setting automatically promotes a secondary region if the write region becomes unavailable?", [("Service-managed failover", "Correct."), ("Session consistency", "Unrelated to failover."), ("Autoscale throughput", "Capacity only."), ("Analytical store", "Analytics only.")], "a", "Service-managed failover promotes a read region by the priority list.", ML + "azure/cosmos-db/high-availability")
